INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Hat jedes Teammitglied im Einliniensystem mehrere Vorgesetzte?', 2, '[{"text": "Nein", "correct": true, "because": "Nur eine Weisungslinie"}, {"text": "Ja", "correct": false, "because": "Keine Mehrfachverantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt diese Struktur am besten?', 3, '[{"text": "Klare Hierarchie", "correct": true, "because": "Direkte Weisungskette"}, {"text": "Flexible Rollen", "correct": false, "because": "Feste Zuständigkeiten"}, {"text": "Teamautonomie", "correct": false, "because": "Zentral gesteuert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet mir diese Organisation?', 5, '[{"text": "Klarheit in Befehlen", "correct": true, "because": "Wenig Missverständnisse"}, {"text": "Schnelle Entscheidungen", "correct": true, "because": "Direkte Weisung"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Wenig Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es gibt nur eine Weisungslinie. b) Entscheidungen sind immer dezentral.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entscheidungen zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung dieser Struktur?', 4, '[{"text": "Hierarchieebenen", "correct": false, "because": "Kern der Struktur"}, {"text": "Weisungsbefugnisse", "correct": false, "because": "Definiert Verantwortung"}, {"text": "Querverbindungen", "correct": true, "because": "Nicht vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Struktur für große Teams geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar mit klarer Linie"}, {"text": "Nein", "correct": false, "because": "Größe kein Hindernis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Ansatz wähle ich für klare Anweisungen?', 3, '[{"text": "Direkte Kommunikation", "correct": true, "because": "Kürzeste Weisungslinie"}, {"text": "Gruppenentscheidung", "correct": false, "because": "Verzögert Prozesse"}, {"text": "Schriftliche Rundmails", "correct": false, "because": "Weniger direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile könnten auftreten?', 5, '[{"text": "Langsame Anpassung", "correct": true, "because": "Strikte Hierarchie"}, {"text": "Überlastung oben", "correct": true, "because": "Zentrale Entscheidungen"}, {"text": "Hohe Autonomie", "correct": false, "because": "Fehlt in der Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Struktur ist einfach. b) Sie fördert Kreativität. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kreativität eingeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht in dieser Organisation?', 4, '[{"text": "Klar definierte Rollen", "correct": false, "because": "Grundlage der Struktur"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Kernprinzip"}, {"text": "Laterale Koordination", "correct": true, "because": "Nur vertikale Linien"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist diese Struktur immer effizient?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Kontext"}, {"text": "Ja", "correct": false, "because": "Flexibilität fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für diese Struktur entscheidend?', 4, '[{"text": "Direkte Berichtslinie", "correct": true, "because": "Definiert Verantwortung"}, {"text": "Klare Befehle", "correct": true, "because": "Vermeidet Verwirrung"}, {"text": "Teamkonsens", "correct": false, "because": "Nicht vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass diese Struktur nur für kleine Firmen passt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für große geeignet"}, {"text": "Ja", "correct": false, "because": "Skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in dieser Organisation?', 3, '[{"text": "Klarheit in der Führung", "correct": true, "because": "Effizienz fördern"}, {"text": "Schnelle Innovation", "correct": false, "because": "Schwer umsetzbar"}, {"text": "Breite Diskussion", "correct": false, "because": "Verzögert Entscheidungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Weisungen sind eindeutig. b) Teams sind selbstständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Selbstständigkeit gering"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stärken hat diese Struktur?', 5, '[{"text": "Einfache Kontrolle", "correct": true, "because": "Zentral gesteuert"}, {"text": "Schnelle Umsetzung", "correct": true, "because": "Klare Anweisungen"}, {"text": "Hohe Kreativität", "correct": false, "because": "Eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in dieser Struktur unwichtig?', 3, '[{"text": "Klare Verantwortung", "correct": false, "because": "Kern der Struktur"}, {"text": "Direkte Weisung", "correct": false, "because": "Grundprinzip"}, {"text": "Abstimmung quer", "correct": true, "because": "Nur vertikal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert diese Struktur Teamarbeit?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Hierarchie"}, {"text": "Ja", "correct": false, "because": "Wenig Querverbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Struktur flexibel ist?', 2, '[{"text": "Nein", "correct": true, "because": "Starr durch Hierarchie"}, {"text": "Ja", "correct": false, "because": "Anpassung schwer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für klare Entscheidungen?', 4, '[{"text": "Linienvorgesetzter", "correct": true, "because": "Direkte Weisungsbefugnis"}, {"text": "Teamleiter quer", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Berater", "correct": false, "because": "Keine Befugnis"}]');
